(* [comment removed for export] *)
Record pst := mkPST {
  ps_c : pcore ; ps_S : list Z ; ps_L : list Z ; ps_ns : NS ; ps_ls : LS ; ps_em : gmap Z elt ;
  ps_h : hdrv ; ps_u : Z ; ps_es : list mbe ; ps_insz : Z ; ps_g : bool ; ps_rdi : byte ;
  ps_LBn : list block ; ps_st : PState ; ps_errv : word }.

(* [comment removed for export] *)
Definition KB : Z := 22.

(* [comment removed for export] *)
Definition body_res (es : list mbe) (insz r : Z) : Z :=
  3 * (insz + r) + 512 - mb_cap es + 31 * (KB - Z.of_nat (length es)).

(* [comment removed for export] *)
Definition new_body_off (LB0 : list block) (SP : Z) (es0 es : list mbe) : Prop :=
  forall x s, In (x, s) es -> In (x, s) es0 \/ (forall a k, rclient_range LB0 SP a k -> 0 <= k -> a + k <= x \/ x + 24 + s <= a).

(* [comment removed for export] *)
Definition put_X (P E : Z) (L0 : list Z) (es0 : list mbe) : list (Z * Z) :=
  (P, P + 242) :: (E, E + 24) :: (G_HTTP_CAT, G_HTTP_CAT + 64) :: (G_FIELD_TABLE, G_FIELD_TABLE + 3456) :: elemsW L0 ++ mb_elemsW es0.

(* [comment removed for export] *)
Definition PUT_STACK : Z := 144 + 80 + IPF_STACK.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition SvOwnP (LB : list block) (ptr len : Z) : Prop := (len = 0 /\ ptr = 0) \/ (1 <= len /\ exists p, In (p, ptr, len) LB).
Definition HdrOwnP (LB : list block) (h : hdrv) : Prop :=
  SvOwnP LB (hv_mp h) (hv_ml h) /\ SvOwnP LB (hv_tp h) (hv_tl h) /\ 0 <= hv_ml h < 2^64 /\ 0 <= hv_tl h < 2^64.
Definition HdrDisjP (em : gmap Z elt) (h : hdrv) : Prop :=
  (1 <= hv_ml h -> em !! (hv_mp h) = None) /\ (1 <= hv_tl h -> em !! (hv_tp h) = None) /\ (1 <= hv_ml h -> 1 <= hv_tl h -> hv_mp h <> hv_tp h).
Definition BodyDisjP (em : gmap Z elt) (h : hdrv) (es : list mbe) : Prop :=
  forall x s, In (x, s) es -> em !! x = None /\ (1 <= hv_ml h -> x <> hv_mp h) /\ (1 <= hv_tl h -> x <> hv_tp h).

(* [comment removed for export] *)
Definition hdr_disj (L : list Z) (es : list mbe) (h : hdrv) : Prop :=
  (hv_tl h <> 0 -> forall e, e ∈ L -> e + 48 <= hv_tp h \/ hv_tp h + hv_tl h <= e)
  /\ (hv_ml h <> 0 -> forall e, e ∈ L -> e + 48 <= hv_mp h \/ hv_mp h + hv_ml h <= e)
  /\ (hv_tl h <> 0 -> forall x s, In (x, s) es -> x + 24 + s <= hv_tp h \/ hv_tp h + hv_tl h <= x)
  /\ (hv_ml h <> 0 -> forall x s, In (x, s) es -> x + 24 + s <= hv_mp h \/ hv_mp h + hv_ml h <= x)
  /\ (hv_ml h <> 0 -> hv_tl h <> 0 -> hv_mp h + hv_ml h <= hv_tp h \/ hv_tp h + hv_tl h <= hv_mp h).

(* [comment removed for export] *)
Definition blk_fresh (LB0 : list block) (SP : Z) (A n : Z) : Prop :=
  forall a k, rclient_range LB0 SP a k -> 0 <= k -> a + k <= A \/ A + n <= a.

(* [comment removed for export] *)
Definition hdr_new (LB0 : list block) (SP : Z) (h0 h : hdrv) : Prop :=
  h = h0 \/ (hdr_empty h0 /\ (hv_tl h <> 0 -> blk_fresh LB0 SP (hv_tp h) (hv_tl h)) /\ (hv_ml h <> 0 -> blk_fresh LB0 SP (hv_mp h) (hv_ml h))).

(* [comment removed for export] *)
Definition svownedP (ptr len : Z) (b : block) : Prop := 1 <= len /\ blk_addr b = ptr /\ blk_size b = len.
Definition mbownedP (es : list mbe) (b : block) : Prop := exists s, In (blk_addr b, s) es /\ blk_size b = mb_block_size s.
Definition lbn_ownedP (L : list Z) (h : hdrv) (es : list mbe) (LBn : list block) : Prop :=
  forall b, In b LBn -> (blk_addr b ∈ L /\ 1 <= blk_size b) \/ svownedP (hv_mp h) (hv_ml h) b \/ svownedP (hv_tp h) (hv_tl h) b \/ mbownedP es b.

(* [comment removed for export] *)
Definition PutU (P p0 : Z) (bs : list byte) (mb : byte) (d : pst) (m : mem) : Prop :=
  FieldsC m (P + 80) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d)
  /\ rw_cells rsegs m (P + O_PR_HDR) (HdrCells (ps_h d)) /\ rw_cells rsegs m (P + O_PR_USED) [C1 (b8 (ps_u d))]
  /\ MBuf m (P + 168) (ps_es d) (ps_insz d) /\ rw_cells rsegs m (P + 232) [C8 (wz (P + 168))]
  /\ rw_cells rsegs m (P + 242) [C1 mb] /\ rw_cells rsegs m (P + 288) [C8 (wz 0)] /\ rw_cells rsegs m (P + 336) [C8 (wz 0)]
  /\ bytes_at rsegs m p0 bs /\ PfTab m /\ FTInit m /\ XStatics m.

(* [comment removed for export] *)
Definition PutL (sp : word) (P p0 : Z) (bs : list byte) (LB0 : list block) (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (d : pst) : Prop :=
  let LB := ps_LBn d ++ LB0 in
  pcore_ok (ps_c d)
  /\ FieldsOwn LB (ps_em d) /\ MBufOwn LB (ps_es d) /\ HdrOwnP LB (ps_h d)
  /\ elems_heap (ps_em d)
  /\ (forall x s, In (x, s) (ps_es d) -> 0 < x /\ x + 24 + s <= hceil /\ (x + 24 + s <= 0x10000 \/ 0xb4000 <= x))
  /\ new_elems_off LB0 (bv_unsigned sp) L0 (ps_L d) /\ new_body_off LB0 (bv_unsigned sp) es0 (ps_es d)
  /\ (forall e, e ∈ ps_L d -> e + 48 <= p0 \/ p0 + Z.of_nat (length bs) <= e)
  /\ (forall x s, In (x, s) (ps_es d) -> p0 + Z.of_nat (length bs) <= x \/ x + 24 + s <= p0)
  /\ (forall e x s, e ∈ ps_L d -> In (x, s) (ps_es d) -> e + 48 <= x \/ x + 24 + s <= e)
  /\ (pc_state (ps_c d) <= 1 -> hdr_empty (ps_h d) /\ ps_u d = 0) /\ 0 <= ps_u d <= 1
  /\ mb_cap (ps_es d) <= 3 * ps_insz d + 512 /\ Z.of_nat (length (ps_es d)) <= KB /\ 0 <= ps_insz d
  /\ (pc_state (ps_c d) = 3 \/ pc_state (ps_c d) = 4 \/ pc_state (ps_c d) = 9 -> 1 <= pc_len (ps_c d))
  /\ hdr_disj (ps_L d) (ps_es d) (ps_h d)
  /\ hdr_new LB0 (bv_unsigned sp) h0 (ps_h d)
  /\ (pc_state (ps_c d) < 10 -> pc_hlim (ps_c d) <= 8192) /\ pc_skip (ps_c d) < 2^62
  /\ lbn_ownedP (ps_L d) (ps_h d) (ps_es d) (ps_LBn d)
  /\ lsub L0 (ps_L d) /\ (forall x s, In (x, s) es0 -> In (x, s) (ps_es d)).

(* [comment removed for export] *)
Definition PutB (LB0 : list block) (p0 R : Z) (MX CX : Z) (d : pst) (p : Z) : Prop :=
  lb_bytes (ps_LBn d ++ LB0) + 17 * pc_hlim (ps_c d) + body_res (ps_es d) (ps_insz d) (R - (p - p0))
       + (if pc_state (ps_c d) <=? 9 then 34 else 0) <= MX
  /\ 4 * Z.of_nat (length (ps_LBn d ++ LB0)) + pc_hlim (ps_c d) + 4 * (KB - Z.of_nat (length (ps_es d)))
       + (if pc_state (ps_c d) <=? 1 then 8 else 0) + (if pc_state (ps_c d) <=? 9 then 2 else 0) <= 4 * CX
  /\ ps_insz d + (R - (p - p0)) <= 2^28.

(* [comment removed for export] *)
Lemma pot_if_range : forall st, 0 <= (if st <=? 9 then 34 else 0) <= 34 /\ 0 <= (if st <=? 9 then 2 else 0) <= 2 /\ 0 <= (if st <=? 1 then 8 else 0) <= 8.
Proof. intros st. destruct (st <=? 9); destruct (st <=? 1); lia. Qed.

(* [comment removed for export] *)
Definition put_pure (sp : word) (P E lo : Z) (p0 : Z) (bs : list byte) : Prop :=
  1 <= Z.of_nat (length bs) /\ lo + PUT_STACK <= bv_unsigned sp /\ 0xb4000 <= lo /\ hceil <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0xb4000 <= p0) /\ p0 + Z.of_nat (length bs) <= hceil
  /\ bv_unsigned sp <= P /\ P + 344 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64 /\ (P + 344 <= E \/ E + 24 <= P)
  /\ bv_unsigned sp mod 16 = 0.

