(* [comment removed for export] *)
Definition WPUT (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64); (G_FIELD_TABLE, G_FIELD_TABLE + 3456); (P + 240, P + 241)]%Z.
