(* [comment removed for export] *)
Definition WG (lo : Z) (sp : word) (P E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -104); (P, P + 80); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64); (P + 240, P + 241)]%Z.
Scheme kc__8 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

(* [comment removed for export] *)
Lemma put_keep : forall (sp tp : word) (LB0 : list block) (P E lo B p0 R : Z) (bs : list byte) (mb : byte) (L0 : list Z) (es0 : list mbe) (h0 : hdrv)
    (d : pst) (m m' m0 : mem) (st : PState) (errv : word),
  put_static sp tp LB0 P E lo B p0 R bs -> PutL sp P p0 bs LB0 L0 es0 h0 d ->
  (forall b, In b LB0 -> blk_addr b + blk_size b <= hceil) ->
  munch (WG lo sp P E) m m' -> wmono rsegs m m' ->
     (rw_cells rsegs m (errno_addr tp) [C4 errv] -> rw_cells rsegs m' (errno_addr tp) [C4 errv])
  /\ (hs_rauxv_ok H m B -> hs_rauxv_ok H m' B)
  /\ (forall LB, hs_RHEAP H st LB m -> hs_RHEAP H st LB m')
  /\ (forall cs, length cs = 13%nat -> rw_cells rsegs m (bv_unsigned sp + -104) (map C8 cs) -> rw_cells rsegs m' (bv_unsigned sp + -104) (map C8 cs))
  /\ ((FieldTabZero m \/ FT m) -> (FieldTabZero m' \/ FT m'))
  /\ (PutU P p0 bs mb d m -> PutU P p0 bs mb d m')
