Lemma put_round10 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_static sp tp LB0 P E lo B p0 R bs ->
  put_at 0x398c0 (ak_st 10) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
  hs_SR H (put_post0 ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb) cf.
Proof.
  intros until cf. intros STAT AT.
  eapply (hh_seq H HH); [eapply (put_call_pf _ _ 10 put_setup10); [lia | lia | reflexivity | exact STAT | exact AT] |].
  intros cf' (q & MID). eapply put_tail10; [exact STAT | exact MID].
Qed.

