(* [comment removed for export] *)
Lemma fh_facts : forall c, pcore_ok c -> pc_state c = 2 ->
  pcore_ok (snd (fh_res c)) /\ pc_hlim (snd (fh_res c)) = pc_hlim c /\ pc_skip (snd (fh_res c)) = pc_skip c /\ 2 <= pc_state (snd (fh_res c))
  /\ (pc_state (snd (fh_res c)) = 3 \/ pc_state (snd (fh_res c)) = 4 \/ pc_state (snd (fh_res c)) = 9 -> 1 <= pc_len (snd (fh_res c)))
  /\ ec_ok (fst (fh_res c)) /\ (fst (fh_res c) = EC_clear \/ http_fail (fst (fh_res c)))
